bool OrganisationCurrency::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("code"))
    {
        if(!validJsonOfField(1, "code", pJson["code"], err, true))
            return false;
    }
    else
    {
        err="The code column cannot be null";
        return false;
    }
    if(pJson.isMember("decimal_places"))
    {
        if(!validJsonOfField(2, "decimal_places", pJson["decimal_places"], err, true))
            return false;
    }
    else
    {
        err="The decimal_places column cannot be null";
        return false;
    }
    if(pJson.isMember("currency_multiplesof"))
    {
        if(!validJsonOfField(3, "currency_multiplesof", pJson["currency_multiplesof"], err, true))
            return false;
    }
    if(pJson.isMember("name"))
    {
        if(!validJsonOfField(4, "name", pJson["name"], err, true))
            return false;
    }
    else
    {
        err="The name column cannot be null";
        return false;
    }
    if(pJson.isMember("display_symbol"))
    {
        if(!validJsonOfField(5, "display_symbol", pJson["display_symbol"], err, true))
            return false;
    }
    if(pJson.isMember("internationalized_name_code"))
    {
        if(!validJsonOfField(6, "internationalized_name_code", pJson["internationalized_name_code"], err, true))
            return false;
    }
    else
    {
        err="The internationalized_name_code column cannot be null";
        return false;
    }
    return true;
}
